import {configurePresentation} from './presentation.js';
import{categories,visibleIds,descendants,readSections,categoryName,normalizeExplorer}from'./explorer-model.js';
export function createExplorer(api){
 const {esc}=api;let mapBounds=null,miniOpen=innerWidth>700;
 const project=()=>api.project(),prefs=()=>normalizeExplorer(project());
 const viewChange=()=>{api.changed();api.renderMap();};
 function collapse(id){const p=prefs();p.collapsedIds=p.collapsedIds.includes(id)?p.collapsedIds.filter(x=>x!==id):[...p.collapsedIds,id];viewChange();}
 function reveal(id,notify=true){const p=prefs();p.category=null;p.favoritesOnly=false;if(p.focusId&&!descendants(project(),p.focusId).has(id))p.focusId=null;
  p.collapsedIds=p.collapsedIds.filter(parent=>!descendants(project(),parent).has(id)||parent===id);if(notify)api.changed();}
 function mount(){
  const canvas=document.querySelector('#canvas');if(!canvas)return;
  canvas.insertAdjacentHTML('beforeend',`<details class="explorer-tools"><summary>Visualização</summary><div class="explorer-options"><div class="option-row"><button id="collapseAll">Recolher ramos</button><button id="expandAll">Expandir tudo</button></div><strong class="small-label">Categorias</strong><div id="legend" class="legend"></div><button id="favoriteFilter" class="wide">☆ Só favoritos</button><button id="clearFilters" class="wide">Limpar filtros</button><button id="presentMap" class="wide">Montar apresentação</button><span id="visibleCount" class="muted small-label"></span></div></details><div id="focusBanner" class="focus-banner" hidden></div><details id="minimapBox" class="minimap-box" ${miniOpen?'open':''}><summary>Minimapa</summary><svg id="minimap" viewBox="0 0 180 110" role="img" aria-label="Minimapa: clique para navegar"></svg></details><div id="compareTray" class="compare-tray" hidden></div><div id="emptyMap" class="empty-map" hidden><strong>Seu mapa começa com uma ideia</strong><p>Clique em + ou pressione N para criar o primeiro bloco.</p></div>`);
  document.querySelector('#presentMap').onclick=()=>configurePresentation(api);
  document.querySelector('#collapseAll').onclick=()=>{prefs().collapsedIds=project().nodes.filter(n=>project().edges.some(e=>e.source===n.id)&&!n.text.startsWith('IDEIAS DE PROJETOS')&&project().edges.some(e=>e.target===n.id)).map(n=>n.id);viewChange();};
  document.querySelector('#expandAll').onclick=()=>{prefs().collapsedIds=[];viewChange();};
  document.querySelector('#favoriteFilter').onclick=()=>{prefs().favoritesOnly=!prefs().favoritesOnly;viewChange();};
  document.querySelector('#clearFilters').onclick=()=>{prefs().category=null;prefs().favoritesOnly=false;viewChange();};
  document.querySelector('#minimapBox').ontoggle=e=>{miniOpen=e.currentTarget.open;};
  document.querySelector('#minimap').onpointerdown=e=>{e.preventDefault();e.stopPropagation();if(!mapBounds)return;const box=e.currentTarget.getBoundingClientRect();const x=mapBounds.x+(e.clientX-box.left)/box.width*mapBounds.w,y=mapBounds.y+(e.clientY-box.top)/box.height*mapBounds.h;const r=canvas.getBoundingClientRect(),v=project().view;v.x=r.width/2-x*v.z;v.y=r.height/2-y*v.z;api.applyView();api.changed();};
  canvas.addEventListener('click',e=>{const b=e.target.closest('[data-collapse]');if(b)collapse(b.dataset.collapse);});
 }
 function render(){
  if(!project()||!document.querySelector('#legend'))return;const p=prefs(),all=project(),ids=visibleIds(all);document.querySelector('#emptyMap').hidden=all.nodes.length>0;
  document.querySelector('#legend').innerHTML=categories.filter(([,c])=>all.nodes.some(n=>n.color.toLowerCase()===c)).concat([...new Set(all.nodes.map(n=>n.color.toLowerCase()))].filter(c=>!categories.some(([,color])=>color===c)).map(c=>['Outra cor',c])).map(([name,color])=>`<button data-category="${color}" aria-pressed="${p.category===color}" class="category-pill ${p.category===color?'active':''}"><span style="background:${color}"></span>${esc(name)}</button>`).join('');
  document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{p.category=p.category===b.dataset.category?null:b.dataset.category;viewChange();api.center();});
  document.querySelector('#favoriteFilter').setAttribute('aria-pressed',String(p.favoritesOnly));document.querySelector('#favoriteFilter').textContent=p.favoritesOnly?'★ Mostrando favoritos':'☆ Só favoritos';
  document.querySelector('#visibleCount').textContent=`${ids.size} de ${all.nodes.length} ideias visíveis`;
  const banner=document.querySelector('#focusBanner'),n=all.nodes.find(n=>n.id===p.focusId);banner.hidden=!n;if(n){banner.innerHTML=`<span>Foco: <strong>${esc(n.text)}</strong></span><button id="leaveFocus">Voltar ao mapa completo</button>`;document.querySelector('#leaveFocus').onclick=()=>{p.focusId=null;viewChange();api.center();};}
  const byId=new Map(all.nodes.map(n=>[n.id,n])),childCounts=new Map();for(const e of all.edges)childCounts.set(e.source,(childCounts.get(e.source)||0)+1);for(const el of document.querySelectorAll('[data-node]')){const n=byId.get(el.dataset.node);if(n.favorite)el.insertAdjacentHTML('beforeend','<span class="node-star" title="Favorito">★</span>');const count=childCounts.get(n.id)||0;if(count)el.insertAdjacentHTML('beforeend',`<button class="node-collapse" data-collapse="${n.id}" aria-label="${p.collapsedIds.includes(n.id)?'Expandir':'Recolher'} ramo de ${esc(n.text)}" aria-expanded="${!p.collapsedIds.includes(n.id)}">${p.collapsedIds.includes(n.id)?'+':'−'} ${count}</button>`);}
  renderTray();renderMinimap();
 }
 function renderMinimap(){
  const svg=document.querySelector('#minimap');if(!svg||!project())return;
  const ids=visibleIds(project()),nodes=project().nodes.filter(n=>ids.has(n.id));if(!nodes.length){svg.innerHTML='<text x="15" y="55" fill="currentColor" font-size="12">Nenhum resultado</text>';mapBounds=null;return;}
  const v=project().view,r=document.querySelector('#canvas').getBoundingClientRect(),view={x:-v.x/v.z,y:-v.y/v.z,w:r.width/v.z,h:r.height/v.z};
  let minX=Math.min(...nodes.map(n=>n.x),view.x),minY=Math.min(...nodes.map(n=>n.y),view.y),maxX=Math.max(...nodes.map(n=>n.x+210),view.x+view.w),maxY=Math.max(...nodes.map(n=>n.y+100),view.y+view.h);let w=maxX-minX+120,h=maxY-minY+120;minX-=60;minY-=60;
  if(w/h>180/110){const nh=w*110/180;minY-=(nh-h)/2;h=nh;}else{const nw=h*180/110;minX-=(nw-w)/2;w=nw;}mapBounds={x:minX,y:minY,w,h};
  const sx=180/w,sy=110/h;svg.innerHTML=nodes.map(n=>`<rect x="${(n.x-minX)*sx}" y="${(n.y-minY)*sy}" width="${Math.max(2,210*sx)}" height="${Math.max(2,84*sy)}" rx="1" fill="${n.color}"/>`).join('')+`<rect x="${(view.x-minX)*sx}" y="${(view.y-minY)*sy}" width="${view.w*sx}" height="${view.h*sy}" fill="#635bdb12" stroke="var(--ink)" stroke-width="1.3"/>`;
 }
 function editField(node,key,value,type){if(api.readonly())return;node[type]||={};node[type][key]=value;api.changed();}
 function enhanceInspector(){
  const n=project()?.nodes.find(n=>n.id===api.selection()),aside=document.querySelector('.inspector');if(!n||!aside)return;
  const sections=readSections(n),labels={problem:'Proposta / problema',operation:'Como funciona',difference:'Diferencial',mvp:'Primeira versão',money:'Monetização'};
  const raw=document.querySelector('#nodeNotes'),label=aside.querySelector('label[for="nodeNotes"]');
  const group=document.createElement('div');group.className='structured-notes';group.innerHTML=Object.entries(labels).map(([key,label])=>`<label for="section-${key}">${label}</label><textarea id="section-${key}" data-section="${key}" rows="${key==='mvp'?3:2}" maxlength="20000" ${api.readonly()?'readonly':''} placeholder="Ainda não definido">${esc(sections[key])}</textarea>`).join('');label.before(group);
  const details=document.createElement('details');details.className='original-notes';details.innerHTML='<summary>Texto original e detalhes preservados</summary>';label.before(details);details.append(label,raw);if(!Object.values(sections).some(Boolean))details.open=true;
  const tools=document.createElement('div');tools.className='idea-tools';tools.innerHTML=`<button id="favoriteNode" aria-pressed="${!!n.favorite}">${n.favorite?'★ Favorito':'☆ Favoritar'}</button><button id="focusIdea">Focar neste ramo</button><button id="compareIdea" aria-pressed="${prefs().compareIds.includes(n.id)}">${prefs().compareIds.includes(n.id)?'Remover comparação':'Comparar ideia'}</button>`;group.before(tools);
  document.querySelector('#favoriteNode').onclick=()=>api.mutate(()=>n.favorite=!n.favorite);
  document.querySelector('#focusIdea').onclick=()=>{prefs().focusId=n.id;prefs().category=null;prefs().favoritesOnly=false;prefs().collapsedIds=prefs().collapsedIds.filter(id=>id!==n.id);viewChange();api.center();};
  document.querySelector('#compareIdea').onclick=()=>{const p=prefs();if(p.compareIds.includes(n.id))p.compareIds=p.compareIds.filter(id=>id!==n.id);else{if(p.compareIds.length===3)return api.toast('Compare até três ideias. Remova uma antes de adicionar outra.');p.compareIds.push(n.id);}viewChange();};
  const review=document.createElement('details');review.className='review-fields';review.innerHTML=`<summary>Critérios para escolher</summary><label for="review-audience">Público</label><textarea id="review-audience" data-review="audience" rows="2" maxlength="10000" placeholder="Quem sente esse problema?" ${api.readonly()?'readonly':''}>${esc(n.review?.audience||'')}</textarea><label for="review-difficulty">Dificuldade estimada por vocês</label><select id="review-difficulty" ${api.readonly()?'disabled':''}>${['Não estimada','Baixa','Média','Alta'].map(value=>`<option ${n.review?.difficulty===value?'selected':''}>${value}</option>`).join('')}</select><label for="review-validation">O que falta validar</label><textarea id="review-validation" data-review="validation" rows="3" maxlength="10000" placeholder="Que hipótese precisamos testar?" ${api.readonly()?'readonly':''}>${esc(n.review?.validation||'')}</textarea>`;details.after(review);
  for(const field of aside.querySelectorAll('[data-section],[data-review],#review-difficulty')){let editing=false;field.oninput=()=>{if(api.readonly())return;if(!editing){api.checkpoint();editing=true;}editField(n,field.dataset.section||field.dataset.review||'difficulty',field.value,field.dataset.section?'sections':'review');};field.onblur=()=>editing=false;}
 }
 function renderTray(){const tray=document.querySelector('#compareTray');if(!tray)return;const p=prefs();tray.hidden=!p.compareIds.length;tray.innerHTML=p.compareIds.map(id=>{const n=project().nodes.find(n=>n.id===id);return`<button data-uncompare="${id}" title="Remover da comparação">${esc(n.text)} ×</button>`;}).join('')+`<button class="primary" id="openComparison">Comparar (${p.compareIds.length}/3)</button>`;tray.querySelectorAll('[data-uncompare]').forEach(b=>b.onclick=()=>{p.compareIds=p.compareIds.filter(id=>id!==b.dataset.uncompare);viewChange();});if(p.compareIds.length)document.querySelector('#openComparison').onclick=showComparison;}
 function showComparison(){
  const nodes=prefs().compareIds.map(id=>project().nodes.find(n=>n.id===id)).filter(Boolean);if(!nodes.length)return;const d=document.createElement('dialog');d.className='comparison-dialog';
  const rows=[['Categoria',n=>categoryName(n)],['Público',n=>n.review?.audience||'Ainda não definido'],['Problema / proposta',n=>readSections(n).problem||'Ainda não definido'],['Primeira versão',n=>readSections(n).mvp||'Ainda não definida'],['Dificuldade',n=>n.review?.difficulty||'Não estimada'],['O que falta validar',n=>n.review?.validation||'Ainda não definido'],['Monetização',n=>readSections(n).money||'Ainda não definida']];
  d.innerHTML=`<button id="closeComparison" class="dialog-close" aria-label="Fechar comparação">×</button><h2>Escolher o próximo projeto</h2><p>Compare as ideias. Preencha público, dificuldade e validação em “Critérios para escolher”, nos detalhes de cada bloco.</p><div class="comparison-scroll"><table><thead><tr><th scope="col">Critério</th>${nodes.map(n=>`<th scope="col"><span class="compare-dot" style="background:${n.color}"></span>${esc(n.text)}</th>`).join('')}</tr></thead><tbody>${rows.map(([title,get])=>`<tr><th scope="row">${title}</th>${nodes.map(n=>`<td>${esc(get(n))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;document.body.append(d);d.showModal();d.querySelector('#closeComparison').onclick=()=>d.remove();d.oncancel=()=>d.remove();
 }
 return{mount,render,renderMinimap,enhanceInspector,reveal,visibleIds:()=>visibleIds(project())};
}
